import time
import pytest
from solution import LoggingMiddleware, LogEntry

@pytest.fixture
def mw():
    return LoggingMiddleware(log_level='INFO')

def _make_entry(method='GET', path='/api/data', status=200, headers=None):
    return LogEntry(
        timestamp=time.time(), method=method, path=path,
        status_code=status, response_time_ms=15.5,
        headers=headers or {}
    )

def test_basic_logging(mw):
    mw.log_request(_make_entry())
    logs = mw.get_logs()
    assert len(logs) == 1
    assert logs[0]['method'] == 'GET'
    assert logs[0]['path'] == '/api/data'

def test_sensitive_headers_redacted(mw):
    mw.log_request(_make_entry(headers={'Authorization': 'Bearer secret123', 'X-Request-Id': 'abc'}))
    logs = mw.get_logs()
    assert logs[0]['headers'].get('Authorization') != 'Bearer secret123'
    assert logs[0]['headers']['X-Request-Id'] == 'abc'

def test_path_filter(mw):
    mw.log_request(_make_entry(path='/api/users'))
    mw.log_request(_make_entry(path='/api/orders'))
    mw.log_request(_make_entry(path='/health'))
    assert len(mw.get_logs('/api')) == 2
    assert len(mw.get_logs('/health')) == 1

def test_clear(mw):
    mw.log_request(_make_entry())
    mw.clear_logs()
    assert len(mw.get_logs()) == 0

def test_multiple_entries(mw):
    for i in range(10):
        mw.log_request(_make_entry(path=f'/api/item/{i}', status=200 + i))
    assert len(mw.get_logs()) == 10
